function maximalSquare(matrix: string[][]): number {
  const m = matrix.length;
  const n = matrix[0].length;
  // Состояние: dp[i][j] — сторона наибольшего квадрата из единиц
  // с правым нижним углом в клетке (i - 1, j - 1).
  // База: лишние нулевые строка и столбец — за границей квадратов нет
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  let maxSide = 0;

  // Порядок: строки сверху вниз, внутри строки слева направо —
  // верх, лево и диагональ уже посчитаны
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      // Ноль не может быть углом квадрата из единиц: dp[i][j] остаётся 0
      if (matrix[i - 1][j - 1] === '1') {
        // Переход: квадрат ограничен самым маленьким из трёх соседних квадратов
        dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
        maxSide = Math.max(maxSide, dp[i][j]);
      }
    }
  }

  // Ответ: площадь, а не сторона
  return maxSide * maxSide;
}

// Время: O(m · n) — каждая клетка один раз
// Память: O(m · n) — полная таблица dp
